head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05232.xml";
scwin.vScrenTpCD = "";
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.vBzProcsNo = "";
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분
scwin.spacYN = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //기업인수목적 회사 구분

scwin.fn_searchCode = function() {
    /*
    004048 -  특례상장구분코드
    04108 - 이전상장구분코드
    */
    var arrCid = [{
        cid: "SPECL_LIST_TP_CD",
        cnm: "cmb_SPECL_LIST_TP_CD"
    }, {
        cid: "PRE_LIST_TP_CD",
        cnm: "cmb_PRE_LIST_TP_CD"
    }];
    var objCod;
    var url = '';
    url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECL_LIST_TP_CD','PRE_LIST_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^선택,";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "6") {
            $c.stf.showObj(label_24, true);
            $c.stf.showObj(label_18, false);
            $c.stf.showObj(label_23, false);
        } else {
            $c.stf.showObj(label_24, false);
            $c.stf.showObj(label_18, true);
            $c.stf.showObj(label_23, true);
        }
        scwin.fn_setComponent();
        scwin.fn_initItem();
        scwin.fn_list_sync();
        buttonSet.setButtonDepCd(dts_ByCorpDepCd, txb_ISUR_CD.getValue(), js_dep_cd);
        buttonSet.setInsertStatus();
    }
};
scwin.fn_setComponent = function() {
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '1') {
        img_DELIST_RSN_DSC.src = "../img/btn_search.gif";
        img_DELIST_RSN_DSC.setDisabled(false);
        txb_DELIST_RSN_DSC.setReadOnly(true);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#b9d4f7';
        img_MKTPARTC_KOR_NM.src = "../img/btn_search_d.gif";
        img_MKTPARTC_KOR_NM.setDisabled(true);
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD == '6') {
        img_DELIST_RSN_DSC.src = "../img/btn_search_d.gif";
        img_DELIST_RSN_DSC.setDisabled(true);
        txb_DELIST_RSN_DSC.setReadOnly(false);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#ffffff';
        img_MKTPARTC_KOR_NM.src = "../img/btn_search.gif";
        img_MKTPARTC_KOR_NM.setDisabled(false);
        $c.stf.setObjectValue(edt_DELIST_ADVNOTI_STRT_DD, '');
        edt_DELIST_ADVNOTI_STRT_DD.setReadOnly(true);
        edt_DELIST_ADVNOTI_STRT_DD.ReadOnlyBackColor = '#b9d4f7';
        img_DELIST_ADVNOTI_STRT_DD.src = "../img/icn_calendar_d.gif";
        $c.stf.setObjectValue(edt_DELIST_ADVNOTI_END_DD, '');
        edt_DELIST_ADVNOTI_END_DD.setReadOnly(true);
        edt_DELIST_ADVNOTI_END_DD.ReadOnlyBackColor = '#b9d4f7';
        img_DELIST_ADVNOTI_END_DD.src = "../img/icn_calendar_d.gif";
        $c.stf.setObjectValue(txb_DELIST_ADVNOTI_PD_DSC, '');
        txb_DELIST_ADVNOTI_PD_DSC.setReadOnly(true);
        txb_DELIST_ADVNOTI_PD_DSC.style.backgroundColor = '#b9d4f7';
        $c.stf.setObjectValue(cmb_PRE_LIST_TP_CD, '');
        $c.stf.setObjectValue(txa_DSC, '');
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '6') {
            cmb_PRE_LIST_TP_CD.setDisabled(false);
            txa_DSC.Enable2 = true;
        } else {
            cmb_PRE_LIST_TP_CD.setDisabled(true);
            txa_DSC.Enable2 = false;
        }
    }
};
scwin.fn_GetParRsn = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "K";
    arrPar[1] = "05";
    arrPar[5] = scwin.spacYN; //기업인수목적 회사 
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParRsn = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_Mst.NameString(1, "DELIST_RSN_CD") = (arrPar.length >= 1 ? arrPar[0] : "");*/
    X = (arrPar.length >= 1 ? arrPar[0] : "");
    txb_DELIST_RSN_DSC.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
    txb_GRND_REGUL_NM.setValue((arrPar.length >= 3 ? arrPar[2] : ""));
};
scwin.fn_SetParMbrNo = function(arrPar) {
    //txb_list_agnccom_mbr_cd.value = (arrPar.length >= 1 ? arrPar[0] : "");

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_Mst.NameString(1, "LIST_AGNCCOM_MBR_NO") = (arrPar.length >= 1 ? arrPar[0] : "");*/
    X = (arrPar.length >= 1 ? arrPar[0] : "");
    txb_MKTPARTC_KOR_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};
scwin.fn_new_read_sync = function() {
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarketNew&inputMessageId=DELISTING_ISU_INOUT&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
    $c.stf.CopyDataSet(dts_Isu, dts_Secu);
};
scwin.fn_list_sync = function() {
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarketDetail&inputMessageId=DELISTING_INOUT&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&MKTACT_APPL_OBJ_TP_CD=2";
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.fn_OpenDetail = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=masterDetail&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
    url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarket&inputMessageId=DELISTING_ISU_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();


    /* 2009.06.08 영문공시관련 추가 */
    url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=masterDetailEng&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Mst_Eng.DataID = encodeURI(url);
    dts_Mst_Eng.reset();
    url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarketEng&inputMessageId=DELISTING_ISU_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu_Eng.DataID = encodeURI(url);
    dts_Isu_Eng.reset();
    /* 2009.06.08 영문공시관련 추가 End */

};
scwin.fn_initItem = function() {
    buttonSet.setInsertStatus();
    dts_Isu.removeAll();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; //초기화 
    $c.stf.setObjectValue(cmb_GRND_REGUL_NM, "");
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[상장폐지 종목]을선택하세요");
        return false;
    }
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        if (dts_Mst.getCellData(1, "DELIST_RSN_CD") == "") {
            $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }

    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2" || scwin.vSPOT_ISU_TRD_MKT_TP_CD == "6") {
        if ($c.stf.getObjectValue(txb_DELIST_RSN_DSC) == "") {
            $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_DELIST_RSN_DSC, 2000, "상장폐지사유")) return false;
    }
    if ($c.stf.getObjectValue(edt_DELIST_ADVNOTI_STRT_DD) != "" || $c.stf.getObjectValue(edt_DELIST_ADVNOTI_END_DD) != "") {
        if ($c.stf.getObjectValue(edt_DELIST_ADVNOTI_STRT_DD) == "") {
            $c.win.alert("[상장폐지예고 시작일]을 입력하세요.");
            edt_DELIST_ADVNOTI_STRT_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_DELIST_ADVNOTI_END_DD) == "") {
            $c.win.alert("[상장폐지예고 종료일]을 입력하세요.");
            edt_DELIST_ADVNOTI_END_DD.focus();
            return false;
        }
        if (!$c.stf.compareFromToDate(edt_DELIST_ADVNOTI_STRT_DD, edt_DELIST_ADVNOTI_END_DD, "상장폐지예고 시작일", "상장폐지예고 종료일")) return false;
    }
    if ($c.stf.getObjectValue(edt_ARRANTRD_MKTACT_ENFORCE_DD) != "" || $c.stf.getObjectValue(edt_ARRANTRD_END_DD) != "") {
        if ($c.stf.getObjectValue(edt_ARRANTRD_MKTACT_ENFORCE_DD) == "") {
            $c.win.alert("[정리매매허용 시작일]을 입력하세요.");
            edt_ARRANTRD_MKTACT_ENFORCE_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_ARRANTRD_END_DD) == "") {
            $c.win.alert("[정리매매허용 종료일]을 입력하세요.");
            edt_ARRANTRD_END_DD.focus();
            return false;
        }
        if (!$c.stf.compareFromToDate(edt_ARRANTRD_MKTACT_ENFORCE_DD, edt_ARRANTRD_END_DD, "정리매매허용 시작일", "정리매매허용 종료일")) return false;
    }
    if ($c.stf.getObjectValue(edt_DELIST_DD) == "") {
        $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_DELIST_DD)) {
        $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_GRND_REGUL_NM) == "") {
        $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_GRND_REGUL_NM, 200, "근거규정")) return false;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2") {
        if (dts_Mst.getCellData(1, "LIST_AGNCCOM_MBR_NO") == "") {
            $c.win.alert("[상장주선인]를 선택하세요.");
            txb_MKTPARTC_KOR_NM.focus();
            return false;
        }
    }
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, $c.stf.getObjectValue(txb_ISUR_CD), $c.stf.getObjectValue(edt_DELIST_DD), scwin.vBzProcsNo, LIST_BZ_TP_CD_200)) {
        return false;
    }

    // 코넥스 이전상장구분 필수값 체크추가 jackal_22.06.24
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == '6') {
        if ($c.stf.getObjectValue(cmb_PRE_LIST_TP_CD) == "") {
            $c.win.alert("[이전상장구분(코넥스)]를 선택하세요.");
            cmb_PRE_LIST_TP_CD.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_save = function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Mst.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
        //alert('[dts_Mst]'+dts_Mst.text);
        scwin.fn_trs();
    }
};
scwin.fn_update = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.fn_trs();
};
scwin.fn_update2 = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    //if (! fn_isProcess('U') )  return ;
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_check_delete_discls(dts_BZ_CHECK, scwin.vBzProcsNo)) return;
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    if (scwin.trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = vBzProcsNo;*/
        X = scwin.vBzProcsNo;
    }


    // 법인별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "2");

    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    trs_Save.Action = $c.lc.fn_encodeNSession("/Delisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveDelList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_200 + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL;
    trs_Save.Post();
};
scwin.fn_CheckBiz = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        return;
    }
    if (scwin.vBzProcsNo == "") {
        $c.win.alert("[대상]를 선택하세요.");
        return;
    }
    return true;
};
scwin.fn_dscl = async function() {
    if (!scwin.fn_CheckBiz()) {
        return;
    }
    if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_Isu)) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;

    /*
    fn_GetPar = function(arr, param_dts_isu, param_dts_mst,param_dts2,param_dts3) {
    	if (vSPOT_ISU_TRD_MKT_TP_CD == "1") { 
