    			arr[0] = "70794";
    		} else {
    			arr[0] = "70769";
    		}
    	}
    */

    /* 2009.06.08 영문공시관련 추가 */
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        //유가
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            arr[0] = "68051A";
            arr[1] = scwin.vBzProcsNo;
            arr[2] = $c.stf.getObjectValue(txb_ISUR_CD);
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
            $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
            $c.stf.CopyDataSet(dts_Isu_Eng, param_dts_isu_eng);
            $c.stf.CopyDataSet(dts_Mst_Eng, param_dts_mst_eng);
            return arr.length;
        };
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2" || scwin.vSPOT_ISU_TRD_MKT_TP_CD == "6") {
        //코스닥,코넥스
        scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            if (scwin.fr_SecuGrpId == SECUGRP_ID_MF) {
                // 액면가가 무액면인지, '0'인지를 발행기관 테이블에서 판단 
                //fn_getParval();
                if (dts_Isu.getCellData(1, "PARVAL") != 0) {
                    arr[0] = "70794";
                } else {
                    //무액면
                    arr[0] = "70794_P";
                }
                //alert("서식코드-->70794");

            } else {
                if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2") {
                    arr[0] = "70769";
                } else {
                    arr[0] = "32007";
                }
                //alert("서식코드-->70769");

            }
            arr[1] = scwin.vBzProcsNo;
            arr[2] = $c.stf.getObjectValue(txb_ISUR_CD);
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
            if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "6") {
                if ($c.stf.getObjectValue(cmb_SPECL_LIST_TP_CD) != "") {
                    $c.stf.setObjectValue(txb_MKTPARTC_KOR_NM, $c.stf.getObjectText(cmb_SPECL_LIST_TP_CD));
                }
            }
            $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
            $c.stf.CopyDataSet(dts_Isu_Eng, param_dts_isu_eng);
            $c.stf.CopyDataSet(dts_Mst_Eng, param_dts_mst_eng);
            return arr.length;
        };
    }
    /* 2009.06.08 영문공시관련 추가 */

    scwin.fn_SetPar = function(arr) {

    };
    var wth = 750 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
    scwin.fn_list_sync();
};
scwin.fn_getParval = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=DELISTING_ISU_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.delist.parval.isuinst.select" + "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}param02=" + scwin.vSPOT_ISU_TRD_MKT_TP_CD;
    dts_getParval.DataID = encodeURI(url);
    dts_getParval.reset();
};
scwin.fn_drft = function() {
    if (!scwin.fn_CheckBiz()) {
        return;
    }
    var OldGet = scwin.fn_GetPar;
    scwin.fn_GetPar = function(arr) {
        arr[0] = scwin.vBzProcsNo;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.fn_GetPar = OldGet;
};


