scwin.fn_chkIsu = function(row) {
    var chkIsu = false;
    if (dts_List.getCellData(row, "DISCLS_YN") == 'Y') {
        for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
            if (dts_Isu.getCellData(i, "LIST_SHRS") != dts_Secu.getCellData(i, "LIST_SHRS")) {
                chkIsu = true;
            }
        }
    }
    if (chkIsu) {
        var res = window.confirm("상장주식수가 변경되었습니다. \n[수정] 처리를 하시겠습니까?");
        if (res) {
            LastJob = '수정';
            scwin.fn_new_read_sync();
            scwin.fn_update2();
        }
    }
};
